def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Every empty starting cell is allowed, and reversed paths are counted
    separately. H and W are at most 10 and K is at most 11.
    """
    cells = [(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.']
    if len(cells) <= K:
        return 0
    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        neighbors.append([index[(nr, nc)]
                          for nr, nc in ((r - 1, c), (r + 1, c),
                                         (r, c - 1), (r, c + 1))
                          if (nr, nc) in index])

    visited = [False] * len(cells)

    def search(cell: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += search(nxt, remaining - 1)
                visited[nxt] = False
        return total

    total = 0
    for start in range(len(cells)):
        visited[start] = True
        total += search(start, K)
        visited[start] = False
    return total

