def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can be changed into t with at most k edits.

    An edit inserts, deletes, or replaces one character. The strings may
    contain up to 500000 characters, and k is at most 20.

    >>> can_transform(3, 'abc', 'awtf')
    True
    >>> can_transform(2, 'abc', 'awtf')
    False
    >>> can_transform(17, 'twothousandtwentyfour', 'happynewyear')
    True
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t or k >= max(n, m):
        return True

    # A diagonal is x - y, where x and y are consumed prefix lengths.
    # For a fixed edit count and diagonal, only the furthest x matters:
    # any earlier position cannot overtake it by following matching chars.
    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    frontier = {0: x}

    for edits in range(1, k + 1):
        following = {}
        for diagonal, x in frontier.items():
            y = x - diagonal
            if x < n:
                # Delete s[x].
                d = diagonal + 1
                if x + 1 > following.get(d, -1):
                    following[d] = x + 1
            if y < m:
                # Insert t[y].
                d = diagonal - 1
                if x > following.get(d, -1):
                    following[d] = x
            if x < n and y < m:
                # Replace s[x] with t[y].
                if x + 1 > following.get(diagonal, -1):
                    following[diagonal] = x + 1

        for diagonal, x in following.items():
            y = x - diagonal
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            following[diagonal] = x
        frontier = following
    return False

