    # A path needs K + 1 cells in a single connected component.
    seen = [False] * len(cells)
    starts = []
    for root in range(len(cells)):
        if seen[root]:
            continue
        component = [root]
        seen[root] = True
        for cell in component:
            for nxt in neighbors[cell]:
                if not seen[nxt]:
                    seen[nxt] = True
                    component.append(nxt)
        if len(component) > K:
            starts.extend(component)

    visited = [False] * len(cells)

    def search(cell: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += search(nxt, remaining - 1)
                visited[nxt] = False
        return total

    total = 0
    for start in starts:
        visited[start] = True
        total += search(start, K)
        visited[start] = False
    return total

