from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length: int, digit_sum: int, divisor: int) -> int:
    """Count nonzero-digit suffixes whose product supplies divisor."""
    if length == 0:
        return int(digit_sum == 0 and divisor == 1)
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    return sum(
        _suffix_count(length - 1, digit_sum - digit, divisor // gcd(divisor, digit))
        for digit in range(max(1, digit_sum - 9 * (length - 1)),
                           min(9, digit_sum - (length - 1)) + 1)
    )


@lru_cache(maxsize=None)
def _possible_sums(length: int) -> tuple:
    # A product of nonzero decimal digits has no other prime factors.
    result = []
    for total in range(1, 9 * length + 1):
        remainder = total
        for prime in (2, 3, 5, 7):
            while remainder % prime == 0:
                remainder //= prime
        if remainder == 1:
            result.append(total)
    return tuple(result)


@lru_cache(maxsize=None)
def _beautiful_length(length: int) -> int:
    return sum(_suffix_count(length, total, total)
               for total in _possible_sums(length))


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    length = len(digits)

    # All positive numbers containing a zero are beautiful.
    # First count the complement: numbers having only nonzero digits.
    nonzero_count = sum(9 ** size for size in range(1, length))
    for position, digit in enumerate(digits):
        if digit == 0:
            break
        nonzero_count += (digit - 1) * 9 ** (length - position - 1)
    else:
        nonzero_count += 1

    beautiful = bound - nonzero_count
    beautiful += sum(_beautiful_length(size) for size in range(1, length))

    prefix_sum = 0
    prefix_product = 1
    possible_sums = _possible_sums(length)
    for position, digit in enumerate(digits):
        remaining = length - position - 1
        for smaller in range(1, digit):
            current_sum = prefix_sum + smaller
            current_product = prefix_product * smaller
            for total in possible_sums:
                beautiful += _suffix_count(
                    remaining,
                    total - current_sum,
                    total // gcd(total, current_product),
                )
        if digit == 0:
            break
        prefix_sum += digit
        prefix_product *= digit
    else:
        beautiful += int(prefix_product % prefix_sum == 0)
    return beautiful


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

