from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree whose degrees are 1 or 4, with a degree-4 vertex.

    The input is an undirected tree on vertices 1 through n. Return -1 if
    no alkane exists. Runs in O(n) time and O(n) space.
    """
    adjacency = [[] for _ in range(n + 1)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)

    parent = [0] * (n + 1)
    order = [1]
    for u in order:
        for v in adjacency[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    # branch[u] includes u and assumes the edge to its parent is selected.
    # Thus u is either a leaf, or has exactly three selected children.
    branch = [1] * (n + 1)
    answer = -1
    for u in reversed(order):
        first = second = third = fourth = 0
        for v in adjacency[u]:
            if v == parent[u]:
                continue
            value = branch[v]
            if value >= first:
                first, second, third, fourth = value, first, second, third
            elif value >= second:
                second, third, fourth = value, second, third
            elif value >= third:
                third, fourth = value, third
            elif value > fourth:
                fourth = value

        if third:
            branch[u] = 1 + first + second + third
            if parent[u]:
                # The highest selected vertex may be u's parent, a leaf.
                answer = max(answer, branch[u] + 1)
        if fourth:
            # Here u itself is the highest selected vertex, of degree four.
            answer = max(answer, 1 + first + second + third + fourth)

    return answer

