def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-color completions of the grid modulo 998244353.

    Every edge-sharing pair must contain different digits. H and W are
    positive and H * W <= 200; fixed digits are preserved.
    """
    mod = 998244353
    # Keep only the shorter dimension on the moving frontier. Its width
    # is at most 14 under the area bound.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Reject an already conflicting edge before building any states.
    for r in range(H):
        for c in range(W):
            digit = grid[r][c]
            if digit != '?':
                if r and grid[r - 1][c] == digit:
                    return 0
                if c and grid[r][c - 1] == digit:
                    return 0

    powers = [3 ** c for c in range(W)]
    # Base-three digits describe the latest processed cell in each column.
    # Before the first row, their initial values are ignored.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            place = powers[c]
            choices = (0, 1, 2) if grid[r][c] == '?' else (int(grid[r][c]) - 1,)
            next_dp = {}
            for state, ways in dp.items():
                above = (state // place) % 3
                left = (state // powers[c - 1]) % 3 if c else -1
                for color in choices:
                    if (r and color == above) or color == left:
                        continue
                    new_state = state + (color - above) * place
                    next_dp[new_state] = (next_dp.get(new_state, 0) + ways) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod
